const grid=document.querySelector('#project-grid');
['baristas','shevy','bloom','jills','silva','serenity','market'].forEach(id=>{const p=projects[id];const article=document.createElement('article');article.className='project';article.dataset.category=p.category;article.innerHTML=`<button class="project-image ${p.portrait?'portrait':''}" style="--bg:${p.color}" data-project="${id}" aria-label="Explore ${p.name}"><img src="assets/${p.image}" alt="${p.name} ${p.category==='brand'?'brand artwork':'design preview'}" loading="lazy" width="1440" height="1000"><span class="project-open" aria-hidden="true">↗</span></button><div class="project-meta"><div><h3><button class="title-button" data-project="${id}">${p.name}</button></h3><p>${p.type}</p></div><span>${p.stage}</span></div>`;grid.append(article);});
const style=document.createElement('style');style.textContent='.title-button{background:none;border:0;padding:0;text-align:left;font:inherit;letter-spacing:inherit;line-height:inherit}.title-button:hover{text-decoration:underline;text-underline-offset:5px}.project:last-child{max-width:100%}';document.head.append(style);
const filters=[...document.querySelectorAll('[data-filter]')];filters.forEach(button=>button.addEventListener('click',()=>{filters.forEach(b=>{b.classList.toggle('active',b===button);b.setAttribute('aria-pressed',String(b===button));});let count=0;grid.querySelectorAll('.project').forEach(card=>{card.hidden=button.dataset.filter!=='all'&&!card.dataset.category.split(' ').includes(button.dataset.filter);if(!card.hidden)count++;});document.querySelector('#filter-result').textContent=`${count} projects shown`; }));
const dialog=document.querySelector('#project-dialog');let opener;
document.addEventListener('click',event=>{const button=event.target.closest('[data-project]');if(!button)return;const p=projects[button.dataset.project];if(!p)return;opener=button;document.querySelector('#dialog-content').innerHTML=`<div class="dialog-hero" style="background:${p.color}"><img src="assets/${p.image}" alt="${p.name} design"></div><div class="dialog-copy"><span class="status">${p.stage}</span><h2 id="dialog-title">${p.name}</h2><p>${p.intro}</p><div class="detail-grid"><div><h3>The idea</h3><p>${p.challenge}</p></div><div><h3>What I made</h3><p>${p.made}</p></div></div><div class="dialog-links">${p.url?`<a class="button" href="${p.url}" target="_blank" rel="noopener noreferrer">${p.link} <span aria-hidden="true">↗</span></a>`:''}<a class="button" href="mailto:jabach811@gmail.com?subject=${encodeURIComponent('Let’s talk about '+p.name)}">Talk about a similar project</a></div>${p.cities?`<nav class="city-links" aria-label="Klemm community previews">${p.cities.map(city=>`<a href="https://klemm-phase2-${city.toLowerCase().replaceAll(' ','-')}.jabach0811.chatgpt.site" target="_blank" rel="noopener noreferrer">${city}</a>`).join('')}</nav>`:''}<p class="detail-note">${p.note}</p></div>`;dialog.showModal();dialog.scrollTop=0;document.querySelector('#close-dialog').focus();});
document.querySelector('#close-dialog').addEventListener('click',()=>dialog.close());dialog.addEventListener('click',event=>{if(event.target===dialog){const r=dialog.getBoundingClientRect();if(event.clientX<r.left||event.clientX>r.right||event.clientY<r.top||event.clientY>r.bottom)dialog.close();}});dialog.addEventListener('close',()=>opener?.focus());
const motion=document.querySelector('#motion');const reduce=matchMedia('(prefers-reduced-motion: reduce)');let paused=false;try{paused=localStorage.getItem('joel-motion')==='paused';}catch{}function syncMotion(){const off=paused||reduce.matches;document.body.classList.toggle('motion-paused',off);motion.setAttribute('aria-pressed',String(off));motion.innerHTML=reduce.matches?'Reduced motion on':off?'<span aria-hidden="true">▷</span> Play motion':'<span aria-hidden="true">Ⅱ</span> Pause motion';motion.disabled=reduce.matches;}syncMotion();reduce.addEventListener('change',syncMotion);motion.addEventListener('click',()=>{paused=!paused;try{localStorage.setItem('joel-motion',paused?'paused':'playing');}catch{}syncMotion();});
